const root=document.querySelector('#report');let request=0;
function el(tag,text,cls){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node}
function link(text,url){const a=el('a',text);a.href=url;a.setAttribute('download','');return a}
async function load(mode){const id=++request;for(const m of ['buggy','fixed'])document.getElementById(m).setAttribute('aria-pressed',String(m===mode));root.textContent='Loading recorded evidence…';try{const base=`runs/${mode}/`;const response=await fetch(base+'report.json');if(!response.ok)throw Error('Report unavailable');const r=await response.json();if(id!==request)return;root.replaceChildren();const summary=el('div',undefined,'summary');summary.append(el('strong',r.verdict==='confirmed'?'Confirmed in two clean contexts':'Fixed control passed twice'));summary.append(el('p',`${r.fixture} fixture · ${new Date(r.created_at).toLocaleString()} · ${r.source}`));const metrics=el('div',undefined,'metrics');for(const [k,v] of [['Browser',`Chromium ${r.environment.chromium}`],['Transport',r.transport],['AI calls','0'],['Recorded actions',r.actions.length]]){const cell=el('span',k);cell.append(el('b',String(v)));metrics.append(cell)}summary.append(metrics);const files=el('div',undefined,'links');files.append(link('Report JSON',base+'report.json'),link('Replay actions',base+'actions.json'),link('Regression script',base+'regression.py'));summary.append(files);root.append(summary);const grid=el('div',undefined,'grid');for(const name of ['exploration','replay']){const phase=r.phases[name];const panel=el('section',undefined,'panel');panel.append(el('h2',name==='exploration'?'01 / First browser run':'02 / Independent replay'));const body=el('div',undefined,'body');body.append(el('p',`Reset → ${r.actions.map(a=>a.name).join(' → ')} → check empty-cart contract`));const observation=el('div',undefined,'observation');for(const [k,v] of [['Before',phase.initial.displayed_total],['After',phase.final.displayed_total],['Expected','$0.00']]){const cell=el('span',k);cell.append(el('b',v));observation.append(cell)}body.append(observation);const img=el('img');img.src=base+phase.screenshots.at(-1);img.alt=`${name}: ${phase.final.quantity} items, total ${phase.final.displayed_total}`;img.loading='lazy';body.append(img,el('p',`Context: ${phase.context_id}`,'context'));const downloads=el('div',undefined,'links');downloads.append(link('Before screenshot',base+phase.screenshots[0]),link('After screenshot',base+phase.screenshots.at(-1)),link('Trace ZIP',base+phase.trace),link('Action log',base+name+'/events.json'));body.append(downloads,el('p',`${phase.duration_ms} ms · ${phase.console.length} console events · ${phase.page_errors.length} page errors`,'note'));panel.append(body);grid.append(panel)}root.append(grid)}catch(e){if(id===request)root.textContent=`Cannot load evidence: ${e.message}`}}
for(const m of ['buggy','fixed'])document.getElementById(m).onclick=()=>load(m);load('buggy');
